import {fetchGoogleWeather} from './google-weather.mjs';
// Credentials and paid results live only in this module's memory, never IndexedDB.
let enabled=false,key='',pointId='',horizon=1,result=null,error='',controller=null;
export function mountGooglePanel(root,{s,T,esc,time,N}){
 const section=document.createElement('div');section.className='card google-weather';root.append(section);
 const points=s.sites; if(!points.some(p=>p.id===pointId)){pointId=points[0]?.id||'';result=null}
 const point=points.find(p=>p.id===pointId);
 if(result&&result.pointKey!==JSON.stringify(point))result=null;
 const paint=()=>{section.innerHTML=`<div class="eyebrow">${T('可选付费数据 · 手动调用','DONNÉES PAYANTES FACULTATIVES')}</div><h2>Google Weather API</h2><p>${T('WeatherNext 3 技术支持；Google综合天气预报，接口不提供模型版本选择。','Technologie WeatherNext 3 ; prévisions intégrées Google, sans sélection de version du modèle.')}</p><label><input id="googleEnabled" type="checkbox" ${enabled?'checked':''}> ${T('启用本次会话的Google接口','Activer Google pour cette session')}</label>${enabled?`<label>${T('Google Maps Demo / Weather API 密钥（仅本次会话）','Clé Google Maps Demo / Weather API (session uniquement)')}</label><input id="googleKey" type="password" autocomplete="off" spellcheck="false" value="${esc(key)}"><p class="note">${T('生产密钥须启用 Weather API 和账单；Demo密钥受Google试用限制。密钥和返回数据不写入备份，关闭应用后清除。','La clé de production nécessite Weather API et la facturation. Les clés Demo ont des limites Google. Clé et résultats ne sont pas sauvegardés et disparaissent à la fermeture.')}</p><div class="toolbar"><select id="googlePoint" aria-label="${T('监测点','Point')}">${points.map(p=>`<option value="${esc(p.id)}" ${p.id===pointId?'selected':''}>${esc(p.pk)} · ${esc(p.name)}</option>`).join('')}</select><select id="googleHours" aria-label="${T('预报时长','Durée')}">${[1,72,168].map(h=>`<option value="${h}" ${h===horizon?'selected':''}>${h} h · ${Math.ceil(h/24)} ${T('次请求','requêtes')}</option>`).join('')}</select></div><p>${T('仅查询选中的一个监测点，每次点击最多','Un seul point ; chaque clic déclenche au maximum')} <strong>${Math.ceil(horizon/24)}</strong> ${T('次可能计费的请求；不参与定时刷新，不自动重试。','requêtes potentiellement facturées, sans actualisation programmée ni nouvel essai automatique.')}</p><div class="toolbar"><button id="googleFetch" class="primary" ${controller||!points.length?'disabled':''}>${controller?T('正在查询…','Chargement…'):T('调用Google付费API','Appeler l’API Google payante')}</button>${controller?`<button id="googleCancel">${T('取消后续请求','Annuler la suite')}</button>`:''}<a href="https://developers.google.com/maps/documentation/weather/usage-and-billing" target="_blank" rel="noopener">${T('Google计费与配额','Tarifs et quotas Google')}</a></div>`:''}<p role="status">${esc(error)}</p>${enabled&&result?`<p>${esc(result.pk)} · ${time(result.fetched/1000)} · ${result.rows.length}/${result.requestedHours} h · ${result.requests} ${T('次请求','requêtes')}${!result.complete?' · '+T('返回时段不完整','Période incomplète'):''}</p><p class="note">${T('以下为Google独立参考数据，不替代上方施工颜色表；概率不是WeatherNext集合成员统计。时间为小时结束时间。','Référence Google indépendante du tableau des travaux ; la probabilité ne représente pas un calcul sur les membres WeatherNext. Heure de fin de période.')}</p><div class="scroll"><table><thead><tr>${[T('小时结束','Fin d’heure'),'mm','°C',T('降雨概率 %','Prob. pluie %'),T('风 m/s','Vent m/s'),T('阵风 m/s','Rafales m/s'),T('雷暴概率 %','Prob. orage %'),T('天气','Conditions')].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${result.rows.map(h=>`<tr>${[time(h.t),N(h.rain),N(h.temp),N(h.prob),N(h.wind),N(h.gust),N(h.thunder),h.description].map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><span style="font:14px Arial,sans-serif;white-space:nowrap">Google Maps</span><br>Source: Includes weather data from Google</p>`:''}`;
 section.querySelector('#googleEnabled').onchange=e=>{enabled=e.target.checked;if(!enabled){controller?.abort();key='';result=null;error=''}paint()};
 if(!enabled)return;
 section.querySelector('#googleKey').oninput=e=>{key=e.target.value;result=null;controller?.abort()};
 section.querySelector('#googlePoint').onchange=e=>{pointId=e.target.value;result=null;controller?.abort();mountAgain()};
 section.querySelector('#googleHours').onchange=e=>{horizon=Number(e.target.value);result=null;controller?.abort();paint()};
 section.querySelector('#googleCancel')?.addEventListener('click',()=>controller?.abort());
 section.querySelector('#googleFetch').onclick=async()=>{if(controller)return;error='';result=null;const selected=points.find(p=>p.id===pointId);if(!key.trim()||!selected){error=T('请填写密钥并选择监测点。','Saisir la clé et choisir un point.');paint();return}controller=new AbortController();const run=controller;paint();try{let data=await fetchGoogleWeather({lat:selected.lat,lon:selected.lon,key,hours:horizon,lang:s.lang,signal:run.signal});if(!run.signal.aborted)result={...data,pk:selected.pk,pointKey:JSON.stringify(selected)}}catch(e){error=e.message}finally{controller=null;if(section.isConnected)paint()}};
 };
 const mountAgain=()=>{section.remove();mountGooglePanel(root,{s,T,esc,time,N})};paint();
}
